// Spell database (Player's Guide, Chapter 7), extracted from the per-spell
// descriptions in the rules reference: name, circle (0 = cantrip), source
// list(s), school, and effect text (stat block + description).

import type { Ability } from './abilities'

export type SpellSource = 'Arcane' | 'Divine' | 'Primordial' | 'Wyrd'

export interface Spell {
  name: string
  circle: number
  sources: SpellSource[]
  school: string
  text: string
}

export const SPELLS: Spell[] = [{"name":"Acid Splash","circle":0,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You conjure a glob of acid to burst over your enemies. Choose one creature within range, or choose two creatures within range that are within 5 feet of each other. A target must succeed on a DEX save or take 1d6 acid damage. This spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."},{"name":"Dancing Lights","circle":0,"sources":["Arcane","Primordial","Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a bit of phosphorus or wychwood, or a glowworm) Duration: Concentration, up to 1 minute By waving a glowworm and chanting, you bring hovering magical lights under your control. You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely Humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius."},{"name":"Druidcraft","circle":0,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Instantaneous You can create a harmless natural effect. Whispering to the spirits of nature, you create one of the following effects within range: • You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round. • You instantly make a flower blossom, a seed pod open, or a leaf bud bloom."},{"name":"Fire Bolt","circle":0,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Instantaneous You send a bolt of fire blazing toward your target. You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn’t being worn or carried. This spell’s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."},{"name":"Grave Touch","circle":0,"sources":["Arcane","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: 1 round You conjure a ghostly hand to attack your target and prevent it from healing. You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can’t regain hit points until the start of your next turn. Until then, the hand clings to the target."},{"name":"Guidance","circle":0,"sources":["Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Concentration, up to 1 minute You grant your target a bonus to its next ability check. You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends. 286 PLAYER'S GUIDE"},{"name":"Light","circle":0,"sources":["Arcane","Divine"],"school":"Evocation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a firefly or phosphorescent moss) Duration: 1 hour You make an object emit bright light. You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action."},{"name":"Mage Hand","circle":0,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: 1 minute You conjure a spectral hand that can perform simple tasks. A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again. You can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial."},{"name":"Mending","circle":0,"sources":["Arcane","Divine"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (two lodestones) Duration: Instantaneous You make minor repairs to an object. This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage. If this spell is used to repair an object with hit points, it can restore up to 1 HP per casting but can’t raise an object’s hit points to more than half its hit point maximum."},{"name":"Message","circle":0,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a short piece of copper wire) Duration: 1 round You send a mental message to your target and allow them to respond. You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear. You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell."},{"name":"Minor Illusion","circle":0,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 30 feet Components: S, M (a bit of fleece) Duration: 1 minute You create a small-scale visual or auditory illusion. You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again. If you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else’s voice, a lion’s roar, a beating of drums, or any other sound you choose."},{"name":"Poison Spray","circle":0,"sources":["Arcane","Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 10 feet Components: V, S Duration: Instantaneous You fling a spume of poison at a nearby target. You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a CON save or take 1d12 poison damage. This spell’s damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12)."},{"name":"Prestidigitation","circle":0,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 10 feet Components: V, S Duration: Up to 1 hour You create a harmless magical effect. This spell is a minor trick that novice spellcasters use for practice. You create one of the following magical effects within range: • You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor. • You instantaneously light or snuff out a candle, a torch, or a small campfire. • You instantaneously clean or soil an object no larger than 1 cubic foot."},{"name":"Produce Flame","circle":0,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 10 minutes You conjure a handheld flame that can light the way or be hurled at enemies. A flickering flame appears in your hand. It remains for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again. You can also attack with the flame, although doing so ends the spell."},{"name":"Ray Of Frost","circle":0,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You create an icy ray that harms and slows your target. A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn. The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},{"name":"Resistance","circle":0,"sources":["Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a miniature cloak) Duration: Concentration, up to 1 minute You give your target a bonus to a save. You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one save of its choice. It can roll the die before or after making the save. The spell then ends. 305 7 SPELLCASTING"},{"name":"Sacred Flame","circle":0,"sources":["Divine"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You attack a creature with searing radiance. Flame-like radiance descends on a creature that you can see within range. The target must succeed on a DEX save or take 1d8 radiant damage. The target gains no benefit from cover for this save. The spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."},{"name":"Shillelagh","circle":0,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (mistletoe, a shamrock leaf, and a club or quarterstaff) Duration: 1 minute You transform a stick or staff into a magic weapon. The wood of a club or quarterstaff you are holding is imbued with nature’s power. For the duration, you can use your spellcasting ability instead of STR for the attack and damage rolls of melee attacks using that weapon, and the weapon’s damage die becomes a d8. The weapon also becomes magical if it isn’t already."},{"name":"Shocking Grasp","circle":0,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Instantaneous Your touch delivers a shock that harms a creature and slows reaction time. Lightning springs from your hand to deliver a shock to a creature you touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing metal armor or armor that lacks the Natural Materials property. On a hit, the target takes 1d8 lightning damage, and it can’t take reactions until the start of its next turn."},{"name":"Spare The Dying","circle":0,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 action Range: 10 feet Components: V, S Duration: Instantaneous You touch a dying creature and stabilize it. You touch a living creature that has 0 HP. The creature becomes stable. This spell has no effect on Constructs or Undead."},{"name":"Thaumaturgy","circle":0,"sources":["Divine","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V Duration: Up to 1 minute You create a minor supernatural effect. You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within range: • Your voice booms up to three times as loud as normal for 1 minute. • You cause flames to flicker, brighten, dim, or change color for 1 minute. • You cause harmless tremors in the ground for 1 minute."},{"name":"Vicious Mockery","circle":0,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You attack a creature with words that damage its psyche and will to fight. You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a WIS save or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn. This spell’s damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4). W"},{"name":"Alarm","circle":1,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (silver hand bell worth at least 10 gp) Duration: 8 hours You ward an area to alert you when intruders pass through. You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you when a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won’t set off the alarm. You also choose whether the alarm is mental or audible."},{"name":"Animal Friendship","circle":1,"sources":["Primordial"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a morsel of food) Duration: 24 hours You charm a Beast or Animal for a day. This spell lets you convince an animal that you mean it no harm. Choose a Beast or creature with the Animal tag that you can see within range. It must see and hear you. If the creature’s INT is 4 (−3) or higher, the spell fails. Otherwise, the creature must succeed on a WIS save or be charmed by you for the spell’s duration. If you or one of your companions harms the target, the spell ends. At Higher Circles."},{"name":"Bane","circle":1,"sources":["Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a drop of blood) Duration: Concentration, up to 1 minute You curse targets with a penalty to attacks and saves. Up to three creatures of your choice that you can see within range must succeed on a CHA save or become cursed. When a cursed target makes an attack roll or a save before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or save. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, you can target one additional creature for each slot above 1st."},{"name":"Bless","circle":1,"sources":["Divine"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a sprinkling of holy water) Duration: Concentration, up to 1 minute You call on the divine to give targets a bonus to attacks and saves. You bless up to three creatures of your choice within range. When a target makes an attack roll or a save before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or save. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, you can target one additional creature for each slot above 1st."},{"name":"Burning Hands","circle":1,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (15-foot cone) Components: V, S Duration: Instantaneous You create a cone of fire that burns creatures and sets objects aflame. A thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a DEX save. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one. The fire ignites any flammable objects in the area that aren’t being worn or carried. At Higher Circles."},{"name":"Charm","circle":1,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: 1 hour Your entrancing words and motions compel your target to trust you. You attempt to charm a creature that you can see within range. To be affected by this spell, the target must be able to understand at least one language, though it need not be a language you speak. The target must make a WIS save and does so with advantage if you or your companions are fighting it. On a failed save, it is charmed by you until the spell ends or until you or your companions do anything harmful to it."},{"name":"Color Spray","circle":1,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: Self (15-foot cone) Components: V, S, M (a pinch of powder or sand that is colored red, yellow, and blue) Duration: 1 round You blind foes with an illusory array of colorful lights. A dazzling array of flashing, colored light springs from your hand. Roll 8d10 and total the result. This total is how many hit points of creatures this spell can affect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can’t see)."},{"name":"Command","circle":1,"sources":["Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You utter a command your target must obey. You speak a one-word command to a creature you can see within range. The target must succeed on a WIS save or follow the command at the start of its next turn. The spell has no effect if the target is Undead, if it doesn’t understand your language, or if your command is directly harmful to it. Some typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves."},{"name":"Comprehend Languages","circle":1,"sources":["Arcane"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S, M (a pinch of soot and salt) Duration: 1 hour You understand any language you hear or read. For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text. This spell doesn’t decode secret messages in a text or a glyph, such as an arcane sigil, that isn’t part of a written language. At Higher Circles."},{"name":"Create Familiar","circle":1,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 hour Range: 5 feet Components: V, S, M (a life-sized statue, puppet, stuffed animal, or other suitable vessel worth at least 10 gp, which the spell consumes) Duration: Instantaneous You gain a helpful animal pet to act as your aide and companion. As part of this ritual, you imbue your chosen vessel with a spark of your own life force to create an arcane familiar."},{"name":"Create Or Destroy Water","circle":1,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a drop of water if creating water or a few grains of sand if destroying it) Duration: Instantaneous You either create or destroy water. When you cast this spell, choose which of the following effects to create. Create Water. You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range, extinguishing exposed flames in the area. Destroy Water. You destroy up to 10 gallons of water in an open container within range."},{"name":"Cure Wounds","circle":1,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Instantaneous You heal a wounded creature with a touch and a word. A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, the healing increases by 1d8 for each slot above 1st. D"},{"name":"Detect Evil And Good","circle":1,"sources":["Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 10 minutes You sense nearby supernatural creatures, places, and objects. For the duration, you know if there is an Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated. The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."},{"name":"Detect Magic","circle":1,"sources":["Arcane","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 10 minutes You sense the presence of nearby magic. For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any. The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."},{"name":"Detect Poison And Disease","circle":1,"sources":["Divine","Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a dried snake rattle) Duration: Concentration, up to 10 minutes You sense nearby poisons, poisonous creatures, and diseases. For the duration, you can sense the presence and location of poisons and diseases within 30 feet of you. This spell also detects the presence of creatures affected by an ongoing poison or disease, creatures that deal poison damage, and creatures that can infect other creatures with a disease, such as ghouls and mummies. You also identify the kind of poison, creature, or disease in each case."},{"name":"Disguise Self","circle":1,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 1 hour You cover yourself with an illusory appearance. You make yourself—including your clothing, armor, weapons, and other belongings on your person—look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can’t change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The changes wrought by this spell fail to hold up to physical inspection."},{"name":"Divine Favor","circle":1,"sources":["Divine"],"school":"Evocation","text":"Casting Time: 1 bonus action Range: Self Components: V, S Duration: Concentration, up to 1 minute You recite a prayer to enhance your weapon’s damage. Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit."},{"name":"Entangle","circle":1,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 90 feet Components: V, S Duration: Concentration, up to 1 minute You create grasping vines that restrain creatures in the area. Grasping weeds and vines sprout from the ground in a 20-foot square starting from a point within range. For the duration, these plants turn the ground in the area into difficult terrain. A creature in the area when you cast the spell must succeed on a STR save or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a STR check against your spell save DC."},{"name":"Expeditious Retreat","circle":1,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 bonus action Range: Self Components: V, S Duration: Concentration, up to 1 minute You gain additional movement each turn. This spell allows you to move at an incredible pace. When you first cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action."},{"name":"Faerie Fire","circle":1,"sources":["Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Concentration, up to 1 minute You illuminate targets with fey radiance that makes them visible and vulnerable to attack. Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a DEX save. For the duration, objects and affected creatures shed dim light in a 10-foot radius."},{"name":"False Life","circle":1,"sources":["Arcane"],"school":"Necromancy","text":"Casting Time: 1 action Range: Self Components: V, S, M (a small amount of alcohol or distilled spirits) Duration: 1 hour You enhance your life force with necromantic preservation. You bolster yourself with a touch of the same necromantic powers used to preserve the dead. You gain 1d4 + 4 temporary hit points for the duration. At Higher Circles. When you cast this spell using a 2nd- circle spell slot or higher, you gain 5 additional temporary hit points for each slot above 1st."},{"name":"Feather Fall","circle":1,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 reaction, when you or a creature within 60 feet of you falls Range: 60 feet Components: V, M (a small feather or piece of down) Duration: 1 minute You throw a feather into the air, to help falling creatures float harmlessly to the ground. Choose up to five falling creatures within range. A falling creature’s rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature. 278 PLAYER'S GUIDE"},{"name":"Find Familiar","circle":1,"sources":["Wyrd"],"school":"Conjuration","text":"Casting Time: 1 hour Range: 10 feet Components: V, S, M (charcoal, incense, and herbs collectively worth 10 gp, which the spell consumes) Duration: Instantaneous You bind a supernatural creature to serve you. You gain the service of a familiar, a spirit that takes one of the following Beast forms you choose: bat , cat , crab , frog (toad) , hawk , lizard , octopus , owl , poisonous snake , fish (quipper) , rat , raven , seahorse , spider , or weasel (see Appendix C: Creature Statistics ). Upon completion of the ritual, your familiar appears in an unoccupied space within 10 feet of you."},{"name":"Fire Under The Tongue","circle":1,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 5 feet Components: V, S Duration: 24 hours You consume fire and hold it until you spit out the flames. You can ingest a nonmagical fire up to the size of a Small campfire within range. The fire is stored harmlessly in your mouth and dissipates without effect if it isn’t expelled before the spell ends. Once ingested, you can spit out the stored fire as an action. If you try to hit a particular target with the flames, treat this as a ranged spell attack with a range of 10 feet."},{"name":"Floating Disk","circle":1,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a drop of mercury) Duration: 1 hour You conjure a floating platform to carry things for you. This spell creates a circular, horizontal plane of force 3 feet in diameter and 1 inch thick that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground. The disk is immobile while you are within 20 feet of it."},{"name":"Fog Cloud","circle":1,"sources":["Arcane","Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 1 hour You conjure a sphere of mist that obscures everything within. You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it. At Higher Circles. When you cast this spell using a 2nd- circle spell slot or higher, the radius of the fog increases by 20 feet for each slot above 1st."},{"name":"Goodberry","circle":1,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a handful of berries) Duration: Instantaneous You transform normal berries into magical healing berries. You transform up to ten berries in your hand, infusing them with magic for up to 24 hours. A creature can use its action to eat one berry. Eating a berry restores 1 HP and provides enough nourishment to sustain a creature for one day, though a creature can’t be sustained by eating berries two or more days in a row. The berries lose their potency if they have not been consumed within 24 hours of the casting of this spell."},{"name":"Grease","circle":1,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a bit of pork rind or butter) Duration: 1 minute With a touch of oily fat, you create an area of slippery grease that causes creatures to fall. Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration. When the grease appears, each creature standing in its area must succeed on a DEX save or fall prone. A creature that enters the area or ends its turn there must also succeed on a DEX save or fall prone."},{"name":"Guiding Bolt","circle":1,"sources":["Divine","Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: 1 round You hurl an energy bolt that damages your target and makes them vulnerable to the next attack. A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then. At Higher Circles."},{"name":"Healing Word","circle":1,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 bonus action Range: 60 feet Components: V Duration: Instantaneous You utter a quick prayer that restores a little health to a nearby creature. A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, the healing increases by 1d4 for each slot above 1st. 287 7 SPELLCASTING"},{"name":"Hellish Rebuke","circle":1,"sources":["Wyrd"],"school":"Evocation","text":"Casting Time: 1 reaction, when damaged by a creature within 60 feet of you that you can see Range: 60 feet Components: V, S Duration: Instantaneous You retaliate against an attacker with a burst of hellfire. You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a DEX save. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, the damage increases by 1d10 for each slot above 1st. 288 PLAYER'S GUIDE"},{"name":"Heroism","circle":1,"sources":["Divine"],"school":"Enchantment","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Concentration, up to 1 minute You touch a willing target, warding it against fear and bolstering its health. A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell. At Higher Circles."},{"name":"Hideous Laughter","circle":1,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (tiny tarts and a feather that is waved in the air) Duration: Concentration, up to 1 minute You infect your target with uncontrollable laughter. A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a WIS save or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an INT of 3 (−4) or lower isn’t affected by this spell."},{"name":"Identify","circle":1,"sources":["Arcane"],"school":"Divination","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a pearl worth at least 100 gp and an owl feather) Duration: Instantaneous You touch an object or a creature to learn its magical properties or any spells affecting it. You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are."},{"name":"Illusory Script","circle":1,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a lead-based ink worth at least 10 gp, which the spell consumes) Duration: 10 days You scribe an illusion of false, hidden, or indiscernible script. You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration. To you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text."},{"name":"Inflict Wounds","circle":1,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Instantaneous You attack a target you touch with harmful energy. Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, the damage increases by 1d10 for each slot above 1st."},{"name":"Longstrider","circle":1,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a pinch of dirt) Duration: 1 hour Your touch enhances a creature’s ability to move and jump. You touch a creature. Its speed increases by 10 feet and its jump distance is tripled until the spell ends. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, you can target one additional creature for each slot above 1st. M"},{"name":"Mage Armor","circle":1,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a piece of cured leather) Duration: 8 hours Your touch weaves magical defenses around an unarmored creature. You touch a willing creature who isn’t wearing armor, and a protective magical force surrounds it until the spell ends. The target’s base AC becomes 13 + its DEX modifier. The spell ends if the target dons armor or if you dismiss the spell as an action."},{"name":"Magic Missile","circle":1,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Instantaneous You launch glowing motes of force guaranteed to hit one or more targets. You create three darts that each hit a creature of your choice you can see within range. You can choose whether the darts hit the same creature or different creatures. Each dart deals 1d4 + 1 force damage to its target. At Higher Circles. When you cast this spell using a spell slot of 2nd circle or higher, it creates one additional dart for each slot above 1st."},{"name":"Pendulum","circle":1,"sources":["Arcane"],"school":"Enchantment","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a small pendulum or metronome made of brass and rosewood worth 10 gp) Duration: Concentration, up to 1 minute You regulate fate for a creature you touch. You give the touched creature an aspect of regularity in its motions and fortunes. An unwilling target must make a WIS save. On a failure, the target doesn’t make d20 checks to determine the results of attack rolls, ability checks, and saves for the duration of the spell. Instead, when it would make a check, its results follow the sequence 1, 20, 2, 19, 3, 18, 4, 17, and so on."},{"name":"Protection From Evil And Good","circle":1,"sources":["Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (holy water or powdered silver and iron, which the spell consumes) Duration: Concentration, up to 10 minutes You ward your target against the attacks of supernatural creatures. Until the spell ends, one willing creature you touch is protected against certain types of creatures: Aberrations, Celestials, Elementals, Fey, Fiends, and Undead. The protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can’t be charmed, frightened, or possessed by them."},{"name":"Purify Food And Drink","circle":1,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: 10 feet Components: V, S Duration: Instantaneous You cleanse food and drink for safe consumption. All nonmagical food and drink within a 5-foot-radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease."},{"name":"Sanctuary","circle":1,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 bonus action Range: 30 feet Components: V, S, M (a small silver mirror) Duration: 1 minute You utter a protective prayer that makes your target difficult to attack. You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a WIS save. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn’t protect the warded creature from area effects, such as the explosion of a fireball ."},{"name":"Shield","circle":1,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 reaction, when you are hit by an attack or targeted by the magic missile spell Range: Self Components: V, S Duration: 1 round You create a magic barrier to repel an incoming attack. An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from darts created by the magic missile spell ."},{"name":"Shield Of Faith","circle":1,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 bonus action Range: 60 feet Components: V, S, M (a small parchment with a bit of holy text written on it) Duration: Concentration, up to 10 minutes You create a ward that enhances a creature’s defenses. A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration."},{"name":"Silent Image","circle":1,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a bit of fleece) Duration: Concentration, up to 10 minutes You create a visual illusion in a small area. You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15‑foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn’t accompanied by sound, smell, or other sensory effects. You can use your action to cause the image to move to any spot within range."},{"name":"Sleep","circle":1,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (a pinch of fine sand, rose petals, or a cricket) Duration: 1 minute You lull creatures into magic-induced slumber. This spell sends creatures into a magical slumber. Roll 8d8; the result is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures)."},{"name":"Speak With Animals","circle":1,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 10 minutes You can understand and speak to animals for a short time. You gain the ability to understand and verbally communicate with Beasts and creatures with the Animal tag for the duration. The knowledge and awareness of such creatures are limited by their INT, but at minimum, targets can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a target to perform a small favor for you, at the GM’s discretion."},{"name":"Thunderwave","circle":1,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (15-foot cube) Components: V, S Duration: Instantaneous You create a booming wave of force that damages creatures and pushes targets away from you. A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a CON save. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn’t pushed."},{"name":"Unseen Servant","circle":1,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 minute Range: 60 feet Components: V, S, M (a piece of string and a bit of wood) Duration: 1 hour You conjure an invisible servant to perform simple tasks for you. This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 HP, a STR of 3 (−4), and it can’t attack. If it drops to 0 HP, the spell ends."},{"name":"Acid Arrow","circle":2,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (powdered rhubarb leaf and an adder’s stomach) Duration: Instantaneous You launch a missile of acid toward your target. A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn. At Higher Circles."},{"name":"Aid","circle":2,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a tiny strip of white cloth) Duration: 8 hours You heal your allies for a small amount and temporarily increase their hit point maximums. Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target’s hit point maximum and current hit points increase by 5 for the duration. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, a target’s hit points increase by an additional 5 for each slot above 2nd."},{"name":"Alter Self","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 1 hour Your body takes on a new appearance, grows natural weapons, or adapts to your environment. You magically alter your form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one. Aquatic Adaptation. You adapt your body to an aquatic environment, sprouting gills and 255 7 SPELLCASTING growing webbing between your fingers."},{"name":"Animal Messenger","circle":2,"sources":["Primordial"],"school":"Enchantment","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a morsel of food) Duration: 24 hours You enlist the aid of a nearby beast to deliver a message for you. Choose a Tiny Beast you can see within range, such as a squirrel, blue jay, or bat. Specify a location, which you must have visited, and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” Then speak a message of up to twenty-five words."},{"name":"Arcane Lock","circle":2,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (gold dust worth at least 25 gp, which the spell consumes) Duration: Until dispelled You magically seal an entryway or container. You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken, or the spell is dispelled or suppressed."},{"name":"Arcanist’S Magic Aura","circle":2,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a small square of silk and burning incense worth at least 10 gp, which the spell consumes) Duration: 24 hours You drape your target in an illusory aura, masking its true nature. You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn’t being carried or worn by another creature. When you cast the spell, choose one or both of the following effects. The effect lasts for the duration."},{"name":"Augury","circle":2,"sources":["Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (specially marked sticks, bones, or similar tokens worth at least 25 gp) Duration: Instantaneous You receive an omen about the potential outcome of your plans. By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes."},{"name":"Barkskin","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a handful of oak bark) Duration: Concentration, up to 1 hour You transform a target’s skin, making it as craggy and resilient as tree bark. You touch a willing creature. Until the spell ends, the creature’s skin has a rough, bark-like appearance, and its AC can’t be less than 16, regardless of the armor it wears."},{"name":"Blindness/Deafness","circle":2,"sources":["Arcane","Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 30 feet Components: V Duration: 1 minute You magically blind or deafen a nearby creature. You can blind or deafen a foe. Choose one creature that you can see within range to make a CON save. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a CON save. On a success, it is no longer affected by the spell. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, you can target one additional creature for each slot above 2nd."},{"name":"Blur","circle":2,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: Self Components: V Duration: Concentration, up to 1 minute You cloak yourself in an illusion that makes you hard to hit. Your body becomes blurred, shifting and wavering to all who can see you. For the duration, creatures have disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn’t rely on sight, as with keensense, or can see through illusions, as with truesight."},{"name":"Branding Smite","circle":2,"sources":["Divine"],"school":"Evocation","text":"Casting Time: 1 bonus action Range: Self Components: V Duration: Concentration, up to 1 minute You empower a weapon with damaging radiance that makes foes visible. The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it’s invisible, and the target sheds dim light in a 5-foot radius and can’t become invisible until the spell ends. At Higher Circles."},{"name":"Calm Emotions","circle":2,"sources":["Divine"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 1 minute With supernatural charm, you soothe a group of people. You attempt to suppress strong emotions in a group of people. Each Humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a CHA save; a creature can choose to fail this save if it wishes. If a creature fails its save, choose one of the following effects. • Suppression. You can suppress any effect causing a target to be charmed or frightened."},{"name":"Circle Of Stones","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: 30 feet (10-foot-radius circle) Components: V, S, M (four or more crystals worth at least 5 gp each) Duration: 8 hours You enchant a ring of magical crystals to attack approaching creatures. You place four crystals on the ground in an area within range that is no larger than a 10-foot-radius circle and imbue them with defensive magic. When you cast this spell, you designate any number of specific creatures or creature types to be ignored by the spell’s magic."},{"name":"Continual Flame","circle":2,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (ruby dust worth 50 gp, which the spell consumes) Duration: Until dispelled You create a heatless flame that lasts until dispelled. A flame equivalent in brightness to a torch springs from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn’t use oxygen. The flame can be covered or hidden but not smothered or quenched."},{"name":"Darkness","circle":2,"sources":["Arcane","Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, M (bat fur and a drop of pitch or piece of coal) Duration: Concentration, up to 10 minutes You conjure a globe of magical darkness. Magical darkness spreads from a point you choose within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can’t see through this darkness, and nonmagical light can’t illuminate it. If the point you choose is on an object you are holding or one that isn’t being worn or carried, the darkness emanates from the object and moves with it."},{"name":"Darkvision","circle":2,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a pinch of dried carrot or an agate) Duration: 8 hours You transform a creature’s eyes to see in the dark. You touch a willing creature to grant it the ability to see in nonmagical darkness. For the duration, that creature has darkvision to a range of 60 feet. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, you can target one additional creature for each slot above 2nd."},{"name":"Detect Thoughts","circle":2,"sources":["Arcane","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S, M (a copper piece) Duration: Concentration, up to 1 minute You reach out to sense the minds and thoughts of others. For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an INT of 3 (−4) or lower or doesn’t speak any languages, the creature is unaffected."},{"name":"Elemental Blade","circle":2,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 bonus action Range: Self Components: V, S, M (a leaf of sumac) Duration: Concentration, up to 10 minutes You throw a leaf into the air, and a blade of elemental energy appears in your hand. You evoke an elemental blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action. When the blade first appears, you decide whether it deals acid, cold, fire, lightning, or thunder damage."},{"name":"Enhance Ability","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (fur or a feather from a beast) Duration: Concentration, up to 1 hour Your touch strengthens a creature’s ability score. You touch a creature and bestow one of the following effects upon it. It gains that effect until the spell ends. Bear’s Endurance. The target has advantage on CON checks and gains 2d6 temporary HP, which are lost when the spell ends. Bull’s Strength. The target has advantage on STR checks, and its carrying capacity doubles. Cat’s Grace. The target has advantage on DEX checks."},{"name":"Enlarge/Reduce","circle":2,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a pinch of powdered iron) Duration: Concentration, up to 1 minute You increase or decrease a target’s size by one category. You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a CON save. On a success, the spell has no effect. If the target is a creature, everything it is wearing and carrying changes size with it."},{"name":"Enthrall","circle":2,"sources":["Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: 1 minute Your words captivate your targets, making other creatures harder to perceive. You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a WIS save. Any creature that can’t be charmed succeeds on this save automatically, and if you or your companions are fighting a creature, it has advantage on the save."},{"name":"Find Steed","circle":2,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S Duration: Instantaneous You conjure a spirit steed and develop a bond with it as rider. You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes a form that you choose: warhorse , pony , camel , elk , or mastiff . (Your GM might allow other animals to be summoned as steeds."},{"name":"Flaming Sphere","circle":2,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a bit of tallow, a pinch of brimstone, and a dusting of powdered iron) Duration: Concentration, up to 1 minute You create a roiling ball of flame that moves on your command. A 5-foot-diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a DEX save. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one. As a bonus action, you can move the sphere up to 30 feet."},{"name":"Gear Barrage","circle":2,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: Self (30-foot cone) Components: V, S, M (a handful of gears worth 5 gp) Duration: Instantaneous You expel a cone of sharp, whirling gears. You conjure a burst of magically propelled gears. Each creature in a 30-foot cone must make a DEX save. On a failure, a creature takes 3d8 slashing damage, or half as much damage on a success. Constructs have disadvantage on this save. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, the damage increases by 1d8 for each slot above 2nd. 283 7 SPELLCASTING"},{"name":"Gentle Repose","circle":2,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a pinch of salt and one copper piece placed on each of the corpse’s eyes, which must remain there for the duration) Duration: 10 days You ward a corpse against decay and necromantic influence. You touch a corpse or other remains. For the duration, the target is protected from decay and can’t become Undead. The spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don’t count against the time limit of spells such as raise dead."},{"name":"Gust Of Wind","circle":2,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (60-foot line) Components: V, S, M (a legume seed) Duration: Concentration, up to 1 minute You emit a continuous line of wind that pushes creatures and clears the air. A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell’s duration. Each creature that starts its turn in the line must succeed on a STR save or be pushed 15 feet away from you in a direction following the line. Any creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you."},{"name":"Heat Metal","circle":2,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a piece of iron and a flame) Duration: Concentration, up to 1 minute You superheat a metal object, harming creatures who touch it. Choose a manufactured metal object (not a creature), such as a metal weapon or a suit of armor that lacks the Natural Materials property, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell."},{"name":"Hold","circle":2,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a small, straight piece of iron) Duration: Concentration, up to 1 minute You paralyze a Medium or smaller creature. Choose a Medium or smaller creature that you can see within range. The target must succeed on a WIS save or be paralyzed for the duration. At the end of each of its turns, an affected target can repeat the WIS save, ending the effect on itself on a success. This spell has no effect on Undead. At Higher Circles."},{"name":"Invisibility","circle":2,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: Touch Components: V, S, M (an eyelash encased in tree sap) Duration: Concentration, up to 1 hour You make a creature invisible for up to an hour, if it doesn’t attack or cast a spell. A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target’s person. The spell ends for a target that attacks or casts a spell. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, you can target one additional creature for each slot above 2nd."},{"name":"Knock","circle":2,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You unlock, unstick, or unbar an object with a single word. Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access. A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked."},{"name":"Levitate","circle":2,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a small leather loop or a piece of golden wire with a long shank on one end) Duration: Concentration, up to 10 minutes You lift your target into the air. One creature or object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a CON save is unaffected."},{"name":"Locate","circle":2,"sources":["Arcane","Divine","Primordial","Wyrd"],"school":"Divination","text":"Casting Time: 1 minute Range: Self (1 mile) Components: V, S, M (a figurine of a bloodhound worth at least 25 gp, which the spell consumes) Duration: Concentration, up to 10 minutes You discern the direction and distance of desired objects or creatures. Describe or name a particular kind of object (such as a certain kind of apparel, jewelry, tool, or weapon) or particular kind of creature (such as a human or a unicorn). If a suitable target is within range of the spell, you sense the direction to the nearest creature or object within the spell’s range."},{"name":"Magic Mouth","circle":2,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a small bit of honeycomb and jade dust worth at least 10 gp, which the spell consumes) Duration: Until dispelled You enchant an object to deliver a short message when the time is right. You implant a message within an object in range, a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn’t being worn or carried by another creature. Then speak the message, which must be twenty-five words or fewer, though it can be delivered over as long as 10 minutes."},{"name":"Magic Weapon","circle":2,"sources":["Arcane","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 bonus action Range: Touch Components: V, S Duration: Concentration, up to 1 hour You enchant a weapon with a magical bonus to attack and damage. You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. At Higher Circles. When you cast this spell using a spell slot of 4th circle or higher, the bonus increases to +2. When you use a spell slot of 6th circle or higher, the bonus increases to +3."},{"name":"Mirror Image","circle":2,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 1 minute You surround yourself with three illusory copies of yourself to deflect enemy attacks. Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it’s impossible to track which image is real. You can use your action to dismiss the illusory duplicates. Each time a creature targets you with an attack during the spell’s duration, roll a d20 to determine whether the attack instead targets one of your duplicates."},{"name":"Misty Step","circle":2,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 bonus action Range: Self Components: V Duration: Instantaneous You quickly teleport a short distance to a spot you can see. Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see."},{"name":"Moonbeam","circle":2,"sources":["Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (several seeds of any moonseed plant and a piece of opalescent feldspar) Duration: Concentration, up to 1 minute You create a continuous beam of moonlight that harms creatures and forces them to reveal their true form. A silvery beam of pale, dim light shines down in a 5-foot‑radius, 40-foot-high cylinder centered on a point you choose within range. When a creature enters the spell’s area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a CON save."},{"name":"Pass Without Trace","circle":2,"sources":["Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self Components: V, S, M (ashes from a burned leaf of mistletoe and sprig of spruce) Duration: Concentration, up to 1 hour You emit an aura of shadow to better hide yourself and creatures near you. A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to DEX (Stealth) checks and can’t be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage."},{"name":"Prayer Of Healing","circle":2,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 10 minutes Range: 30 feet Components: V Duration: Instantaneous You heal a large group of creatures. Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. Once you cast this spell, you can’t do so again until you complete a long rest. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 3rd-circle spell slots or higher, the healing increases by 1d8 for each slot above 3rd."},{"name":"Protection From Poison","circle":2,"sources":["Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: 1 hour You touch a creature, neutralizing a poison affecting it and protecting it against other poisons. You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random. For the duration, the target has advantage on saves against being poisoned, and it has resistance to poison damage . At Higher Circles."},{"name":"Ray Of Enfeeblement","circle":2,"sources":["Arcane","Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 1 minute You shoot a beam of energy that drains your target’s strength. A beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with attacks that use STR until the spell ends. At the end of each of the target’s turns, it can make a CON save against the spell. On a success, the spell ends."},{"name":"Restoration","circle":2,"sources":["Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Instantaneous Your touch ends one disease or condition afflicting a creature. You touch a creature and can end one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned."},{"name":"Rope Trick","circle":2,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a length of rope up to 60 feet long) Duration: 1 hour You open a portal to a small extradimensional space accessible via climbing rope. You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends. The extradimensional space can be reached by climbing to the top of the rope."},{"name":"Scorching Ray","circle":2,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Instantaneous You launch fiery rays at your chosen targets. You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several. Make a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage. At Higher Circles. When you cast this spell using a spell slot of 3rd circle or higher, you create one additional ray for each slot above 2nd."},{"name":"See Invisibility","circle":2,"sources":["Arcane","Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S, M (a pinch of talc and a small sprinkling of powdered silver) Duration: 1 hour You can see ethereal and invisible creatures and objects. For the duration, you see invisible creatures and objects as if they were visible, and you can see into the Ethereal Plane. Ethereal creatures and objects appear ghostly and translucent."},{"name":"Shatter","circle":2,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a chip of mica) Duration: Instantaneous You create a thunderous burst of sound that harms creatures and destroys objects. A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot-radius sphere centered on that point must make a CON save. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a success. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this save."},{"name":"Silence","circle":2,"sources":["Divine","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 10 minutes You create a globe of silence that deafens creatures and prevents all verbal spellcasting. For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it. Casting a spell that includes a verbal component is impossible while inside the sphere."},{"name":"Spider Climb","circle":2,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a drop of bitumen and a spider) Duration: Concentration, up to 1 hour You grant the ability to walk up walls, ceilings, and vertical surfaces such as trees or cliffs. Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings while leaving its hands free. The target also gains a climbing speed equal to its walking speed. 311 7 SPELLCASTING"},{"name":"Spike Growth","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 150 feet Components: V, S, M (seven sharp thorns or seven sharpened twigs) Duration: Concentration, up to 10 minutes You create a concealed patch of difficult terrain full of harmful thorns. The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels. The transformation of the ground is camouflaged to look natural."},{"name":"Spiritual Weapon","circle":2,"sources":["Divine","Wyrd"],"school":"Evocation","text":"Casting Time: 1 bonus action Range: 60 feet Components: V, S Duration: Instantaneous You create a ghostly weapon that fights at your command. You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. The weapon can take any form you choose. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier."},{"name":"Suggestion","circle":2,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, M (a snake’s tongue and either a bit of honeycomb or a drop of sweet oil) Duration: Concentration, up to 8 hours You compel a creature to follow a suggested course of action. You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can’t be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable."},{"name":"Warding Bond","circle":2,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a pair of platinum rings worth at least 50 gp each, which you and the target must wear for the duration) Duration: 1 hour You bless a pair of rings to link you to another creature, affording them protection, but you share their pain. This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saves, and it has resistance to all damage."},{"name":"Web","circle":2,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a bit of spiderweb) Duration: Concentration, up to 1 hour You conjure a swath of flammable webs that restrain creatures. You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area."},{"name":"Wildsense","circle":2,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 action Range: Touch Components: S Duration: 1 hour You perceive the world through a willing creature’s senses. You touch a willing Beast or creature with the Animal tag, creating a mystic link that lasts for the duration. While linked, you can use an action to see through the target’s eyes, hear what it hears, and perceive what it perceives via any of its special senses. You are blinded and deafened while using the target’s senses. As an action, you can resume use of your own senses. At any time, you can use an action to break the link completely, ending the spell."},{"name":"Zone Of Truth","circle":2,"sources":["Divine"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: 10 minutes You create an area in which creatures can’t lie. You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell’s area for the first time on a turn or starts its turn there must make a CHA save. On a failed save, a creature can’t speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its save."},{"name":"Animate Dead","circle":3,"sources":["Arcane","Divine"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (a bloodstone worth at least 10 gp, which the spell consumes) Duration: Instantaneous You transform a corpse into an undead servant. This spell creates an Undead servant. Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an Undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse."},{"name":"Beacon Of Hope","circle":3,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self (30-foot radius) Components: V, S Duration: Concentration, up to 1 minute You bolster the will and healing of creatures close to you. This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on WIS saves and death saves, and regains the maximum number of hit points possible from any healing."},{"name":"Bestow Curse","circle":3,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Concentration, up to 1 minute You inflict a creature you touch with a weakness of your choosing. You touch a creature, and that creature must succeed on a WIS save or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options: • Choose one ability. While cursed, the target has disadvantage on ability checks and saves made with that ability. • While cursed, the target has disadvantage on attack rolls against you."},{"name":"Blink","circle":3,"sources":["Arcane","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 1 minute You phase in and out of your current plane, avoiding harm via the Ethereal Plane. Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (if you were on the Ethereal Plane when you cast the spell, the spell fails and the casting is wasted)."},{"name":"Call Lightning","circle":3,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 10 minutes You conjure a storm cloud that shoots a lightning strike each round. A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can’t see a point in the air where the storm cloud could appear (for example, if you are in a room that can’t accommodate the cloud). When you cast the spell, choose a point you can see within range."},{"name":"Clairvoyance","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Divination","text":"Casting Time: 10 minutes Range: 1 mile Components: V, S, M (a focus worth at least 100 gp, either a jeweled horn for hearing or a glass eye for seeing) Duration: Concentration, up to 10 minutes You conjure a small, invisible sphere through which you can spy and sense nearby locations. You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees)."},{"name":"Conjure Animals","circle":3,"sources":["Primordial","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 1 hour With an ancient word of power, you compel spirits to appear as everyday beasts. You summon Fey spirits that take the form of Beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: • One Beast of CR 2 or lower • Two Beasts of CR 1 or lower • Four Beasts of CR 1/2 or lower • Eight Beasts of CR 1/4 or lower Each Beast is also considered Fey, and it disappears when it drops to 0 HP or when the spell ends."},{"name":"Counterspell","circle":3,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 reaction, when you see a creature within 60 feet of you casting a spell Range: 60 feet Components: S Duration: Instantaneous With rippling motions, you prevent a creature you can see from casting a spell. You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd circle or lower, its spell automatically fails and has no effect. If it is casting a spell of 4th circle or above, make an ability check using your spellcasting ability. The DC equals 10 + the spell’s circle."},{"name":"Create Food And Water","circle":3,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Instantaneous You conjure enough food and water to sustain a large group. You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to twenty Large or smaller creatures for 24 hours. The food is bland but nourishing but spoils if uneaten after 24 hours. The water is clean and doesn’t go bad."},{"name":"Daylight","circle":3,"sources":["Divine","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: 1 hour You create a sphere of daylight that banishes magical darkness. A 60-foot-radius sphere of daylight spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet. If you choose a point on an object you are holding or one that isn’t being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light."},{"name":"Dispel Magic","circle":3,"sources":["Arcane","Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Instantaneous You dismiss an ongoing spell with a cutting motion and sharp word. Choose one creature, object, or magical effect within range. Any spell of 3rd circle or lower on the target ends. For each spell of 4th circle or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell’s circle. On a successful check, the spell ends. At Higher Circles."},{"name":"Fear","circle":3,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: Self (30-foot cone) Components: V, S, M (a white feather or the heart of a hen) Duration: Concentration, up to 1 minute You frighten creatures with illusory images of their worst fears. You project a phantasmal image of a creature’s worst fears. Each creature in a 30-foot cone must succeed on a WIS save or drop whatever it is holding and become frightened of you for the duration. While frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move."},{"name":"Fireball","circle":3,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 150 feet Components: V, S, M (a tiny ball of bat guano and sulfur) Duration: Instantaneous You hurl a ball of flame that explodes, harming creatures and igniting objects in a large area. A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot- radius sphere centered on that point must make a DEX save. A target takes 8d6 fire damage on a failed save, or half as much damage on a success. The fire spreads around corners."},{"name":"Fly","circle":3,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a wing feather from any bird) Duration: Concentration, up to 10 minutes You give a creature the ability to fly. You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall. At Higher Circles. When you cast this spell using a 4th- circle spell slot or higher, you can target one additional creature for each slot above 3rd."},{"name":"Gaseous Form","circle":3,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a bit of gauze and a wisp of smoke) Duration: Concentration, up to 1 hour You transform a creature into a malleable, slow-moving cloud of mist. You transform a willing creature you touch, along with everything it’s wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 HP. An incorporeal creature isn’t affected. While in this form, the target’s only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature."},{"name":"Glyph Of Warding","circle":3,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (incense and powdered diamond worth at least 200 gp, which the spell consumes) Duration: Until dispelled or triggered You ward a small area with a near-invisible mark that explodes or casts a spell. When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph."},{"name":"Haste","circle":3,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a shaving of licorice root) Duration: Concentration, up to 1 minute You grant your target magical speed, making them hard to hit and faster to hit back. Choose a willing creature that you can see within range. Until the spell ends, the target’s speed is doubled, it gains a +2 bonus to AC, it has advantage on DEX saves, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action."},{"name":"Hypnotic Pattern","circle":3,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet Components: S, M (a glowing stick of incense or a crystal vial filled with phosphorescent material) Duration: Concentration, up to 1 minute You create mesmerizing colors that charm creatures who can see them. You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a WIS save. On a failure, the creature becomes charmed for the duration."},{"name":"Lightning Bolt","circle":3,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (100-foot line) Components: V, S, M (a bit of fur and a rod of amber, crystal, or glass) Duration: Instantaneous You send a line of electricity lancing out from your fingertips. A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a DEX save. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one. The lightning ignites flammable objects in the area that aren’t being worn or carried. At Higher Circles."},{"name":"Magic Circle","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (holy water or powdered silver and iron worth at least 100 gp, which the spell consumes) Duration: 1 hour You circle a small location with warding magic and arcane runes, barring access for certain foes. You create a 10-foot-radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the cylinder intersects with the floor or other surface. Choose one or more of the following types of creatures: Celestials, Elementals, Fey, Fiends, or Undead."},{"name":"Major Image","circle":3,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a bit of fleece) Duration: Concentration, up to 10 minutes You conjure an intricate illusion that functions at your mental command. You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted."},{"name":"Mass Healing Word","circle":3,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 bonus action Range: 60 feet Components: V Duration: Instantaneous You swiftly heal nearby creatures. As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. At Higher Circles. When you cast this spell using a spell slot of 4th circle or higher, the healing increases by 1d4 for each slot above 3rd."},{"name":"Meld Into Stone","circle":3,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: 8 hours You fuse yourself into a nearby stone surface for hours. You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with it for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses."},{"name":"Nondetection","circle":3,"sources":["Arcane","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes) Duration: 8 hours Your touch hides a target from divination and scrying. For the duration, you hide a target that you touch from divination magic. The target can be a willing creature, place, or object no larger than 10 feet in any dimension. The target can’t be targeted by any divination magic or perceived through magical scrying sensors. P"},{"name":"Phantom Steed","circle":3,"sources":["Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (an apple made of gold worth 5 gp) Duration: 1 hour You conjure a ghostly mount that can run at incredible speed for a short time. A Large, quasi-real, horse-like creature appears on the ground in an unoccupied space of your choice within range. You decide the creature’s appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is ever more than 10 feet away from the steed."},{"name":"Plant Growth","circle":3,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action or 8 hours Range: 150 feet Components: V, S Duration: Instantaneous You either help normal plants grow wildly to slow movement or you make crops double their yield. There are two possible uses for this spell, depending on its casting time, granting either immediate or long-term benefits. If you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves."},{"name":"Protection From Energy","circle":3,"sources":["Arcane","Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Concentration, up to 1 hour You ward your target against one type of elemental damage. For the duration, one willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder."},{"name":"Remove Curse","circle":3,"sources":["Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Instantaneous Your touch breaks a curse afflicting a target. At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner’s attunement to the object so it can be removed or discarded."},{"name":"Revivify","circle":3,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S, M (diamonds worth 300 gp, which the spell consumes) Duration: Instantaneous You restore a recently slain creature to life. You touch a creature that has died within the last minute. That creature returns to life with 1 HP. This spell can’t return to life a creature that has died of old age, nor can it restore any missing body parts. 306 PLAYER'S GUIDE"},{"name":"Sending","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: Unlimited Components: V, S, M (a short piece of fine copper wire) Duration: 1 round You direct a mental message that your target can understand and respond to. You send a message of twenty-five words or fewer to a creature with whom you are familiar. Regardless of INT and language, the creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately."},{"name":"Sleet Storm","circle":3,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 150 feet Components: V, S, M (a pinch of dust and a few drops of water) Duration: Concentration, up to 1 minute You conjure a sleet storm that hampers movement and concentration. Until the spell ends, freezing rain and sleet fall in a 20-foot- tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames are doused. The ground in the area is covered with slick ice, making it difficult terrain."},{"name":"Slow","circle":3,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a drop of molasses) Duration: Concentration, up to 1 minute You lengthen time around your targets, reducing their reaction time. You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a WIS save or be affected by this spell for the duration. An affected target’s speed is halved, it takes a −2 penalty to AC and DEX saves, and it can’t use reactions. On its turn, it can use either an action or a bonus action, not both."},{"name":"Speak With Dead","circle":3,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (burning incense) Duration: 10 minutes You bestow sentience on a corpse long enough to ask it five questions. You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can’t be Undead. The spell fails if the corpse was the target of this spell within the last 10 days. Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew."},{"name":"Speak With Plants","circle":3,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self (30-foot radius) Components: V, S Duration: 10 minutes You awaken a crude intelligence in nearby plants that allows you to speak with and command them. You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell’s area within the past day, gaining information about creatures that have passed, weather, and other circumstances."},{"name":"Spirit Guardians","circle":3,"sources":["Divine","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: Self (15-foot radius) Components: V, S, M (a memento from a dead person) Duration: Concentration, up to 10 minutes You summon a swarm of spirits to guard you and harry nearby foes. You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. When you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature’s speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a WIS save."},{"name":"Stinking Cloud","circle":3,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (a rotten egg or several skunk cabbage leaves) Duration: Concentration, up to 1 minute You conjure a cloud that sickens creatures caught within it. You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration. Each creature that is completely within the cloud at the start of its turn must make a CON save against poison."},{"name":"Tiny Hut","circle":3,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 10 minutes Range: Self (10-foot-radius dome) Components: V, S, M (a small crystal bead) Duration: 8 hours You create a protective dome to shield yourself and creatures near you. A 10-foot-radius, immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area. Nine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures."},{"name":"Tongues","circle":3,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a small clay model of a ziggurat) Duration: 1 hour Your target can understand every language, and their speech is understood by all creatures. This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says."},{"name":"Trestle","circle":3,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a 1-inch piece of green vine, which the spell consumes) Duration: Until destroyed or dispelled You empower a climbable vine to grow supernaturally quickly. You cause a vine to sprout from the ground and crawl across a surface or rise into the air in a direction you choose. The vine must sprout from a solid surface (such as the ground or a wall), and it is strong enough to support 600 pounds of weight along its entire length, which can be a number of feet up to 5 × the highest Primordial circle you have access to."},{"name":"Vampiric Touch","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 1 minute You touch a creature to drain its life force, then use it to heal yourself. The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action. At Higher Circles."},{"name":"Water Breathing","circle":3,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a short reed or a piece of straw) Duration: 24 hours You grant a large group of creatures the ability to breathe underwater. This spell grants up to ten willing creatures you can see within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration."},{"name":"Water Walk","circle":3,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a piece of cork) Duration: 1 hour You grant creatures the ability to walk across liquid surfaces. This spell grants the ability to move across any liquid surface—water, acid, mud, snow, quicksand, or lava— as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration. If you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round."},{"name":"Wind Wall","circle":3,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a tiny fan and a feather) Duration: Concentration, up to 1 minute You conjure a wall of swirling winds that buffets nearby creatures and whisks away flimsy projectiles and airborne gasses. A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration."},{"name":"Arcane Eye","circle":4,"sources":["Arcane"],"school":"Divination","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a bit of bat fur) Duration: Concentration, up to 1 hour You manifest a movable and invisible eye that you can look through. You create an invisible, magical eye within range that hovers in the air for the duration. You mentally receive visual information from the eye, which has normal vision and darkvision to a range of 30 feet. The eye can look in every direction. As an action, you can move the eye up to 30 feet in any direction."},{"name":"Banishment","circle":4,"sources":["Arcane","Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (an item distasteful to the target) Duration: Concentration, up to 1 minute You banish a creature to another plane for a short while. You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a CHA save or be banished. If the target is native to the plane of existence you’re on, you banish the target to a harmless demiplane. While there, the target is incapacitated."},{"name":"Black Tentacles","circle":4,"sources":["Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (a piece of tentacle from a giant octopus or a giant squid) Duration: Concentration, up to 1 minute You conjure up a mass of writhing tentacles to bludgeon and restrain creatures. Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain."},{"name":"Blight","circle":4,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Instantaneous You siphon moisture and vitality from a nearby creature or plant. Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a CON save. It takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. This spell has no effect on Constructs or Undead. If you target a Plant creature or a magical plant, it makes the save with disadvantage, and the spell deals maximum damage to it."},{"name":"Briar Rose","circle":4,"sources":["Primordial"],"school":"Enchantment","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a rose or similar flower cut within the past 24 hours and ritual oils worth 100 gp, which the spell consumes) Duration: 10 days You imbue a flower with magic that lulls those who touch it into magical slumber. You spend an hour anointing a rose (or similar flower) with scented oils and imbuing it with potent magic, transforming it into a magic flower for the duration. The first creature other than you that touches the flower before the spell ends must make a CHA save."},{"name":"Compulsion","circle":4,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Concentration, up to 1 minute You compel a creature to move in a direction you choose each round. Creatures of your choice that you can see within range and that can hear you must make a WIS save. A target automatically succeeds on this save if it can’t be charmed. On a failed save, a target is affected by this spell. Until the spell ends, you can use a bonus action on each of your turns to designate a direction that is horizontal to you."},{"name":"Confusion","circle":4,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (three nut shells) Duration: Concentration, up to 1 minute You juggle three nuts, speak nonsense, and befuddle creatures to act in a random way each turn. This spell assaults and twists creatures’ minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a WIS save when you cast this spell or be affected by it."},{"name":"Conjure Minor Elementals","circle":4,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M Duration: Concentration, up to 1 hour You summon a cohort of elemental creatures. You summon Elemental creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: • One Elemental creature of CR 2 or lower • Two Elemental creatures of CR 1 or lower • Four Elemental creatures of CR 1/2 or lower A summoned creature disappears when it drops to 0 HP or when the spell ends. The summoned creatures are friendly to you and your companions."},{"name":"Conjure Woodland Beings","circle":4,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a holly berry for each creature summoned) Duration: Concentration, up to 1 hour You summon a cohort of fey creatures. You summon Fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears: • One Fey creature of CR 2 or lower • Two Fey creatures of CR 1 or lower • Four Fey creatures of CR 1/2 or lower A summoned creature disappears when it drops to 0 HP or when the spell ends. The summoned creatures are friendly to you and your companions."},{"name":"Control Water","circle":4,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 300 feet Components: V, S, M (a drop of water and a pinch of dust) Duration: Concentration, up to 10 minutes You command a body of water to flood, part, flow, and swirl. Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one. Flood. You cause the level of all standing water in the area to rise by as much as 20 feet."},{"name":"Death Ward","circle":4,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: 8 hours Your touch grants a warding against death. The first time the target of this spell would drop to 0 HP as a result of taking damage, the target instead drops to 1 HP, and the spell ends. If the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends."},{"name":"Dimension Door","circle":4,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 500 feet Components: V Duration: Instantaneous You teleport yourself and one other creature to a spot you can see or visualize. You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as “200 feet straight downward” or “upward to the northwest at a 45-degree angle, 300 feet.” You can bring along objects as long as their weight doesn’t exceed what you can carry."},{"name":"Divination","circle":4,"sources":["Divine"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (incense or a sacrificial offering appropriate for your religion worth 25 gp, which the spell consumes) Duration: 1 minute You contact a divine being to read the future or answer questions about the present. Your magic and an offering put you in contact with your deity or divine proxy. When you cast this spell, you can use it in one of the following ways: • Read the Future. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply."},{"name":"Elemental Shield","circle":4,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: Self Components: V, S, M (a bit of phosphorus or a firefly) Duration: 10 minutes A ward of flames envelops you to stave off intense heat or fierce cold and attackers. Elemental energy wreathes your body for the duration, shedding bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell early by using an action to dismiss it. When the shield first appears, you decide whether it is made of acid, cold, fire, lightning, or thunder energy. The shield grants you resistance to the damage of your chosen elemental type."},{"name":"Fabricate","circle":4,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: 120 feet Components: V, S Duration: Instantaneous You create fully functional, crafted objects from unworked materials. You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool. Choose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given 334 PLAYER'S GUIDE a sufficient quantity of raw material."},{"name":"Faithful Hound","circle":4,"sources":["Divine","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a tiny silver whistle, a piece of bone, and a thread) Duration: 8 hours You conjure an invisible watchdog that stands guard and attacks trespassers. You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it. The hound is invisible to all creatures except you and can’t be harmed."},{"name":"Freedom Of Movement","circle":4,"sources":["Arcane","Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a leather strap, bound around the arm or a similar appendage) Duration: 1 hour You touch a creature to protect it against immobility and confinement. You touch a willing creature. For the duration, the target’s movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target’s speed nor cause the target to be paralyzed or restrained. The target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled."},{"name":"Giant Insect","circle":4,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Concentration, up to 10 minutes You enlarge nearby insects and command them to fight for you. You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede , a spider becomes a giant spider , a wasp becomes a giant wasp , and a scorpion becomes a giant scorpion . Each creature obeys your verbal commands, and in combat, they act on your turn each round."},{"name":"Greater Invisibility","circle":4,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: Concentration, up to 1 minute You make a creature you touch invisible for a short time. You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target’s person. 285 7 SPELLCASTING"},{"name":"Guardian Of Faith","circle":4,"sources":["Divine"],"school":"Conjuration","text":"Casting Time: 1 action Range: 30 feet Components: V Duration: 8 hours You utter a prayer and summon a ghostly warrior to guard a fixed area. A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your faith. Any creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a DEX save."},{"name":"Hallucinatory Terrain","circle":4,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: 300 feet Components: V, S, M (a stone, a twig, and a bit of green plant) Duration: 24 hours You blanket an area with illusions to make it look like a different kind of natural terrain. You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road."},{"name":"Ice Storm","circle":4,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 300 feet Components: S, M (a pinch of dust and a few drops of water) Duration: Instantaneous You create a torrent of hailstones that deals significant damage and creates difficult terrain. A hail of rock-hard ice pounds to the ground in a 20-foot- radius, 40-foot-high cylinder centered on a point within range. Each creature in the cylinder must make a DEX save. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one."},{"name":"Mass Faerie Fire","circle":4,"sources":["Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 90 feet Components: V Duration: Concentration, up to 1 minute You illuminate targets in three different areas with radiance that makes them visible and vulnerable to attack. You can place up to three 20-foot cubes each centered on a point you can see within range. Each object in a cube is outlined in blue, green, or violet light (your choice). Any creature in a cube when the spell is cast is also outlined in light if it fails a DEX save. A creature in the area of more than one cube is affected only once."},{"name":"Phantasmal Killer","circle":4,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 1 minute You use a creature’s worst nightmares to frighten it and damage its mind. You tap into the nightmares of a creature you can see within range and create an illusory manifestation of its deepest fears, visible only to that creature. The target must make a WIS save. On a failed save, the target becomes frightened of you for the duration. At the end of each of the target’s turns before the spell ends, the target must succeed on a WIS save or take 4d10 psychic damage."},{"name":"Polymorph","circle":4,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a caterpillar cocoon) Duration: Concentration, up to 1 hour You transform a creature into a beast. This spell transforms a creature that you can see within range into a new form. The new form can be any Beast whose challenge rating is equal to or less than the target’s challenge rating (or the target’s level, if it doesn’t have a challenge rating). The target’s game statistics, including INT, WIS, and CHA, are replaced by those of the chosen Beast. It retains its personality."},{"name":"Private Sanctum","circle":4,"sources":["Arcane","Divine"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: 120 feet Components: V, S, M (a thin sheet of lead, a piece of opaque glass, a wad of cloth, and powdered chrysolite) Duration: 24 hours You magically secure an area with magical tricks and defensive properties. You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it."},{"name":"Resilient Sphere","circle":4,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic) Duration: Concentration, up to 1 minute You seal your target in an impermeable and movable sphere. A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a DEX save. On a failed save, the creature is enclosed for the duration."},{"name":"Secret Chest","circle":4,"sources":["Arcane","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (an exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp and a Tiny replica made from the same materials worth at least 50 gp) Duration: Instantaneous You conceal a chest on the Ethereal Plane, which you can access and send back as needed. You hide a chest and all its contents on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet)."},{"name":"Song Of The Forest","circle":4,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a dried leaf, crumpled and released) Duration: Concentration, up to 10 minutes Your senses become supernaturally keen, so you can perceive near- inaudible sounds. You attune your senses to the natural world so that you can detect every sound that occurs within 60 feet of you. You can clearly picture the source of each sound in your mind. While the spell is active, you have tremorsense to a range of 10 feet, darkvision to a range of 30 feet, and you have advantage on WIS (Perception) checks."},{"name":"Stone Shape","circle":4,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (soft clay, which must be worked into roughly the desired shape of the stone object) Duration: Instantaneous You can mold a stone object you touch as if it were soft clay. You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. For example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick."},{"name":"Stoneskin","circle":4,"sources":["Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (diamond dust worth 100 gp, which the spell consumes) Duration: Concentration, up to 1 hour Your touch makes a creature’s skin hard enough to resist mundane damage. This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage."},{"name":"Wall Of Fire","circle":4,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a small piece of phosphorus) Duration: Concentration, up to 1 minute You create a wall of roiling flame that burns nearby creatures. You create a wall of fire on a solid surface within range. You can make the wall in a line up to 60 feet long, 20 feet high, and 1 foot thick or in a circle up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration. When the wall appears, each creature within its area must make a DEX save."},{"name":"Animate Objects","circle":5,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 1 minute You cause nearby objects to spring to life and obey your instructions. Objects come to life at your command. Choose up to ten nonmagical objects within range that aren't being worn or carried. Medium targets count as two objects, Large targets count as four objects, and Huge targets count as eight objects. You can’t animate any object larger than Huge."},{"name":"Antilife Shell","circle":5,"sources":["Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self (10-foot radius) Components: V, S Duration: Concentration, up to 1 hour You surround yourself with a ward that prevents living things from passing through. A shimmering barrier extends out from you in a 10-foot radius and moves with you. It remains centered on you, hedging out creatures other than Undead and Constructs. The barrier lasts for the duration. The barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier."},{"name":"Arcane Hand","circle":5,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (an eggshell and a snakeskin glove) Duration: Concentration, up to 1 minute You create a Large hand made of magical energy capable of striking, pushing, grabbing, or blocking foes. You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell’s duration, and it moves at your command, mimicking the movements of your own hand. The hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 HP, the spell ends."},{"name":"Awaken","circle":5,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 8 hours Range: Touch Components: V, S, M (an agate worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You imbue a beast or plant with permanent sentience. After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller Beast or Plant. The target must have no INT or an INT of 3 (−4) or lower to be affected by this spell. The target gains INT of 10 (+0) and the ability to speak one language you know."},{"name":"Cloudkill","circle":5,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 120 feet Components: V, S Duration: Concentration, up to 10 minutes You conjure up a cloud that poisons creatures within it. You create a 20-foot-radius sphere of poisonous, yellow- green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured. When a creature enters the spell’s area for the first time on a turn or starts its turn there, that creature must make a CON save."},{"name":"Commune With Nature","circle":5,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a forked stick, a bowl of purified water, and a polished stone or bone of an animal native to where you are) Duration: Instantaneous You become one with nature, gaining knowledge of the surrounding territory. You must be outdoors to cast this spell. When you do so, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn’t function where nature has been replaced by construction, such as in dungeons and towns."},{"name":"Cone Of Cold","circle":5,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (60-foot cone) Components: V, S, M (a small crystal or glass cone) Duration: Instantaneous You shoot a powerful cone of frosty air from your hands. A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a CON save. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one. A creature killed by this spell becomes a frozen statue until it thaws. At Higher Circles. When you cast this spell using a spell slot of 6th circle or higher, the damage increases by 1d8 for each circle above 5th."},{"name":"Conjure Elemental","circle":5,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water) Duration: Concentration, up to 1 hour Using elemental materials, you summon a powerful Elemental ally. You summon an Elemental servant that appears in an unoccupied space you can see within range. Choose which Elemental appears: an air elemental, earth elemental, a fire elemental, or a water elemental. The GM has the creature’s statistics."},{"name":"Contact Other Plane","circle":5,"sources":["Arcane","Wyrd"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, M (incense or a sacrificial offering appropriate for the entity contacted worth 25 gp, which the spell consumes) Duration: 1 minute You contact a being from another plane to answer questions. You mentally contact a demigod, the spirit of a long-dead sage, or some entity from another plane. Contacting this extraplanar being can strain or even break your mind. When you cast this spell, make a DC 15 INT save. On a failure, you take 6d6 psychic damage and become incapacitated until you finish a long rest."},{"name":"Contagion","circle":5,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: 7 days You touch a creature and inflict it with a debilitating disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice selected from the options below. At the end of each of the target’s turns, it must make a CON save. After failing three of these saves, the disease’s effects last for the duration, and the creature stops making these saves. After succeeding on three of these saves, the creature recovers from the disease and the spell ends."},{"name":"Creation","circle":5,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a tiny piece of matter of the same type of the item you plan to create) Duration: Special You transform wisps of shadow into nonliving matter that lasts for a short time. You pull wisps of shadow from the Shadow Realm to create a nonliving object or vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal."},{"name":"Dispel Evil And Good","circle":5,"sources":["Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self Components: V, S, M (holy water or powdered silver and iron) Duration: Concentration, up to 1 minute You ward yourself against supernatural creatures and can end their influence or return them to their home plane. Shimmering energy surrounds and protects you from certain types of creatures: Celestials, Elementals, Fey, Fiends, Undead, and creatures with the Outsider tag. Creatures of those types have disadvantage on attack rolls against you. You can end the spell early by using either of the following special functions. Break Enchantment."},{"name":"Dominate","circle":5,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 1 minute You charm a Medium or smaller creature, and gain telepathic control of their actions. Choose a Medium or smaller creature that you can see within range. This spell has no effect on creatures immune to the charmed condition. The target must succeed on a WIS save or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the save."},{"name":"Dream","circle":5,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: Special Components: V, S, M (a handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird) Duration: 8 hours You enter a creature’s dream to shape it or deliver a message. This spell shapes a creature’s dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don’t sleep, such as elves, can’t be contacted by this spell. You or a willing creature you touch enters a trance state, acting as a messenger."},{"name":"Flame Strike","circle":5,"sources":["Divine"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a pinch of sulfur) Duration: Instantaneous You call down a column of blazing radiance to immolate your foes. A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot-radius, 40-foot-high cylinder centered on a point within range must make a DEX save. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a success. At Higher Circles."},{"name":"Geas","circle":5,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 minute Range: 60 feet Components: V, M (a set of silver manacles worth 50 gp, which the spell consumes) Duration: 30 days You compel a creature to either perform a service or refrain from an activity for many days. You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a WIS save or become charmed by you for the duration."},{"name":"Greater Hold","circle":5,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (a small, straight piece of iron) Duration: Concentration, up to 1 minute You paralyze a creature. Choose any creature that you can see within range. The target must succeed on a WIS save or be paralyzed for the duration. At the end of each of its turns, an affected target can repeat the WIS save, ending the effect on itself on a success. This spell has no effect on Undead. At Higher Circles. When you cast this spell using a spell slot of 6th circle or higher, you can target one additional creature for each slot above 5th."},{"name":"Greater Restoration","circle":5,"sources":["Divine","Primordial"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (diamond dust worth at least 100 gp, which the spell consumes) Duration: Instantaneous Your touch alleviates exhaustion or ends a magical curse, condition, or other ailment. You imbue a creature you touch with positive energy to undo a debilitating effect."},{"name":"Hallow","circle":5,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 24 hours Range: Touch Components: V, S, M (herbs, oils, and incense worth at least 1,000 gp, which the spell consumes) Duration: Until dispelled You ward an area against extraplanar interlopers and give it an additional effect. You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect of a hallow spell. The affected area is subject to the following effects."},{"name":"Insect Plague","circle":5,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 300 feet Components: V, S, M (a few grains of sugar, some kernels of grain, and a smear of fat) Duration: Concentration, up to 10 minutes You conjure a swarm of locusts that hamper movement and damage creatures. Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere’s area is difficult terrain. When the area appears, each creature in it must make a CON save."},{"name":"Legend Lore","circle":5,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 1 action Range: Self Components: V, S, M (incense worth at least 250 gp, which the spell consumes) Duration: Instantaneous You instantly learn significant lore about a person, place, or object of legendary importance. Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn’t of legendary importance, you gain no information."},{"name":"Mass Cure Wounds","circle":5,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet (30-foot-radius sphere) Components: V, S Duration: Instantaneous You heal the wounds of up to six creatures. A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot-radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. At Higher Circles. When you cast this spell using a spell slot of 6th circle or higher, the healing increases by 1d8 for each slot above 5th."},{"name":"Mislead","circle":5,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: Self Components: S Duration: Concentration, up to 1 hour You become invisible and create an illusory copy of yourself that moves and speaks as you direct, and you share the copy’s senses. You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell. You can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose."},{"name":"Modify Memory","circle":5,"sources":["Arcane"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Concentration, up to 1 minute You attempt to reshape another creature’s memories. One creature that you can see must make a WIS save. If you are fighting the creature, it has advantage on the save. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target’s memories are modified."},{"name":"Passwall","circle":5,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a pinch of sesame seeds) Duration: 1 hour You create a passageway in a solid surface. A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening’s dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it."},{"name":"Planar Binding","circle":5,"sources":["Arcane","Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 hour Range: 60 feet Components: V, S, M (a jewel worth at least 1,000 gp, which the spell consumes) Duration: 24 hours You bind an extraplanar creature into your service. You attempt to bind a Celestial, an Elemental, a Fey, or a Fiend into your service. The creature must be within range for the entire casting of the spell. Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast. At the completion of the casting, the target must make a CHA save."},{"name":"Raise Dead","circle":5,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 500 gp, which the spell consumes) Duration: Instantaneous You return a creature that has died in the past ten days to life. You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature’s soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 HP. This spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died."},{"name":"Reincarnate","circle":5,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (rare oils and unguents worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous This long ritual brings a dead soul back to life in a completely new body. You touch a dead Humanoid or a piece of a dead Humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target’s soul isn’t free or willing to do so, the spell fails."},{"name":"Scrying","circle":5,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a focus worth at least 1,000 gp such as a crystal ball, a silver mirror, or a font filled with holy water) Duration: Concentration, up to 10 minutes You can spy on a particular creature or location. You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a WIS save, the DC for which is modified by how well you know the target and the sort of physical connection you have to it."},{"name":"Seeming","circle":5,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: 8 hours You disguise any creature within range with an illusory appearance. This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a CHA save, and if it succeeds, it is unaffected by this spell. The spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between."},{"name":"Telekinesis","circle":5,"sources":["Arcane","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 10 minutes You can move creatures and objects with your mind for the duration of the spell. You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each round for the duration, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round, or choose a new one at any time."},{"name":"Telepathic Bond","circle":5,"sources":["Arcane","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (pieces of eggshell from two different kinds of creatures) Duration: 1 hour You create a telepathic link between willing creatures for one hour. You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures with an INT of 3 (−4) or lower aren’t affected by this spell. Until the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language."},{"name":"Teleportation Circle","circle":5,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 minute Range: 10 feet Components: V, M (rare chalks and inks infused with precious gems worth 50 gp, which the spell consumes) Duration: 1 round You create a portal that allows you to teleport to a defined location. As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn."},{"name":"Tree Stride","circle":5,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 1 minute You enter a tree and teleport to emerge from a different tree. You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you’re in."},{"name":"Wall Of Force","circle":5,"sources":["Arcane","Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a pinch of powder made by crushing a clear gemstone) Duration: Concentration, up to 10 minutes You create an invisible wall, dome, or sphere of impassable energy. An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface."},{"name":"Wall Of Stone","circle":5,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a small block of granite) Duration: Concentration, up to 10 minutes You create a wall, bridge, or ramp made of stone. A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick."},{"name":"Blade Barrier","circle":6,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 90 feet Components: V, S Duration: Concentration, up to 10 minutes You speak a word and gesture to call up a wall of deadly, spinning blades. You create a vertical wall of whirling, razor-sharp blades made of magical energy within the spell’s range. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three‑quarters cover to creatures behind it, and its space is difficult terrain."},{"name":"Chain Lightning","circle":6,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 150 feet Components: V, S, M (a bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins) Duration: Instantaneous You create a bolt of lightning that splits and hits four targets. You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts. A target must make a DEX save."},{"name":"Circle Of Death","circle":6,"sources":["Arcane","Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 150 feet Components: V, S, M (the powder of a crushed black pearl) Duration: Instantaneous You emit a sphere of harmful energy that rots and decays nearby creatures. A sphere of negative energy ripples out in a 60-foot-radius sphere from a point within range. Each creature in that area must make a CON save. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one. At Higher Circles. When you cast this spell using a spell slot of 7th circle or higher, the damage increases by 2d6 for each slot above 6th."},{"name":"Contingency","circle":6,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp) Duration: 10 days You prepare another spell to activate when certain conditions are met. Choose a spell of 5th circle or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell—called the contingent spell—as part of casting contingency , expending a spell slot for the contingent spell, but the contingent spell doesn’t come into effect. Instead, it takes effect when a certain circumstance occurs."},{"name":"Create Undead","circle":6,"sources":["Arcane","Divine"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (one pot filled with grave dirt, one pot filled with brackish water, and one 150 gp black onyx stone for each corpse, which the spell consumes) Duration: Instantaneous You transform corpses into potent undead creatures under your command. You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each corpse becomes a ghoul under your control (the GM has statistics for these creatures)."},{"name":"Disintegrate","circle":6,"sources":["Arcane","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a lodestone and pinch of dust) Duration: Instantaneous You emit a ray that utterly destroys a target, reducing it to dust. A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by a wall of force spell. A creature targeted by this spell must make a DEX save. On a failed save, the target takes 10d6 + 40 force damage. If this damage reduces the target to 0 HP, it is disintegrated."},{"name":"Eyebite","circle":6,"sources":["Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S Duration: Concentration, up to 1 minute You transform your eyes into wells of eldritch power; creatures you gaze upon fall unconscious, panic, or become sick. For the spell’s duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a WIS save or be affected by one of the following effects of your choice for the duration."},{"name":"Find The Path","circle":6,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a set of divinatory tools—such as bones, ivory sticks, cards, teeth, or carved runes—worth 100 gp and an object from the location you wish to find) Duration: Concentration, up to 1 day You divine the most direct way to reach your chosen destination. This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence."},{"name":"Flesh To Stone","circle":6,"sources":["Divine"],"school":"Transmutation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a pinch of lime, water, and earth) Duration: Concentration, up to 1 minute You turn a creature into stone. You attempt to turn one creature that you can see within range into stone. If the target’s body is made of flesh, the creature must make a CON save. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn’t affected. A creature restrained by this spell must make another CON save at the end of each of its turns. If it successfully saves against this spell three times, the spell ends."},{"name":"Forbiddance","circle":6,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (a sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp) Duration: 1 day You ward a local area against the teleportation and trespassing of extraplanar creatures. You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can’t teleport into the area or use portals, such as those created by the gate spell, to enter the area."},{"name":"Freezing Sphere","circle":6,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 300 feet (60-foot-radius sphere) Components: V, S, M (a small crystal sphere) Duration: Instantaneous You create a globe of frost that damages creatures and freezes liquids in a large area. A frigid globe of cold energy streaks from your fingertips to a point of your choice within range, where it explodes in a 60-foot-radius sphere. Each creature within the area must 282 PLAYER'S GUIDE make a CON save. A creature takes 10d6 cold damage on a failed save, or half as much damage on a successful one."},{"name":"Globe Of Invulnerability","circle":6,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self (10-foot radius) Components: V, S, M (a glass or crystal bead that shatters when the spell ends) Duration: Concentration, up to 1 minute You surround yourself with a sphere that protects everything within from spells. An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration."},{"name":"Guards And Wards","circle":6,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (burning incense, a small measure of brimstone and oil, a knotted string, and a silver rod worth at least 10 gp) Duration: 24 hours You protect a location with bewildering effects and cunning obstacles. You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall and shaped as you desire."},{"name":"Harm","circle":6,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You infect a creature with a disease that damages them and reduces their hit point maximum for one hour. You unleash a virulent disease on a creature that you can see within range. The target must make a CON save. On a failure, it takes 14d6 necrotic damage, or half as much damage on a success. The damage can’t reduce the target’s hit points below 1. If the target fails the save, its hit point maximum is reduced for 1 hour by an amount equal to the necrotic damage it took."},{"name":"Heal","circle":6,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You heal a creature for a massive amount and simultaneously end all physical afflictions affecting it. Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 HP. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on Constructs or Undead. At Higher Circles. When you cast this spell using a spell slot of 7th circle or higher, the amount of healing increases by 10 HP for each slot above 6th."},{"name":"Heroes’ Feast","circle":6,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a gem-encrusted bowl worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You conjure a bountiful and delicious feast that fills bellies and uplifts spirits. You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve other creatures can partake of the feast. A creature that partakes of the feast gains several benefits."},{"name":"Instant Summons","circle":6,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a sapphire worth 1,000 gp) Duration: Until dispelled You mystically mark an object, allowing you to summon it to your hand from any distance or plane. You touch an item weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire."},{"name":"Irresistible Dance","circle":6,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 30 feet Components: V Duration: Concentration, up to 1 minute You compel a creature to dance in place, hampering its attack and making it easier to hit. Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping its feet, and capering for the duration. Creatures that can’t be charmed are immune to this spell. A dancing creature must use all its movement to dance without leaving its space and has disadvantage on DEX saves and attack rolls."},{"name":"Magic Jar","circle":6,"sources":["Wyrd"],"school":"Necromancy","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a gem, crystal, or ornamental container worth at least 500 gp) Duration: Until dispelled You place your soul in a magic container, allowing you to possess a different creature and trap their soul in the process. Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell’s material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container’s space. You can’t move or use reactions."},{"name":"Mass Suggestion","circle":6,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, M (a snake’s tongue and either a bit of honeycomb or a drop of sweet oil) Duration: 24 hours You compel a group of creatures to follow a suggested course of activity. You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can’t be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable."},{"name":"Move Earth","circle":6,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (an iron blade and a small bag containing a mixture of soils—clay, loam, and sand) Duration: Concentration, up to 2 hours You reshape an area of dirt, sand, or clay. Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area’s elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can’t exceed half the area’s largest dimension."},{"name":"Planar Ally","circle":6,"sources":["Divine","Wyrd"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 60 feet Components: V, S Duration: Instantaneous You chant the names and praises of an extraplanar creature to bargain for their support and services. You beseech an otherworldly entity for aid. The being must be known to you: a god, a demon prince, or some other being of cosmic power. That entity sends a Celestial, an Elemental, or a Fiend loyal to it to aid you, making the creature appear in an unoccupied space within range."},{"name":"Programmed Illusion","circle":6,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a bit of fleece and jade worth at least 25 gp) Duration: Until dispelled You create a complex illusion activated by a specific trigger. You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific condition occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes."},{"name":"Sunbeam","circle":6,"sources":["Divine","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (60-foot line) Components: V, S, M (a magnifying glass) Duration: Concentration, up to 1 minute You hold a magnifying glass and a line of searing, blinding sunlight springs from your hand. A beam of brilliant light flashes out from your hand in a 5-foot-wide, 60-foot-long line. Each creature in the line must make a CON save. On a failure, a creature takes 6d8 radiant damage and is blinded until your next turn. On a success, it takes half as much damage and isn’t blinded by this spell. Undead have disadvantage on this save."},{"name":"Transport Via Plants","circle":6,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: 10 feet Components: V, S Duration: 1 round You transform a nearby plant into a portal that can teleport creatures to a different plant. This spell creates a magical link between a Large or larger nonmagical plant within range and another plant, at any distance, on the same plane of existence. Creatures of the Plant type can’t be targeted by this spell. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement."},{"name":"True Seeing","circle":6,"sources":["Arcane","Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 action Range: Touch Components: V, S, M (ointment made from powdered mushrooms and saffron worth 25 gp, which the spell consumes) Duration: 1 hour You touch a willing creature and grant it truesight. You touch a willing creature to grant it the ability to see things as they actually are. For the duration, that creature has truesight to a range of 120 feet. At Higher Circles. When you cast this spell using a spell slot of 7th circle or higher, you can target one additional creature for each slot above 6th. V"},{"name":"Wall Of Ice","circle":6,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a small piece of quartz) Duration: Concentration, up to 10 minutes You create a wall, dome, or sphere of solid ice that damages nearby creatures. You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration."},{"name":"Wall Of Thorns","circle":6,"sources":["Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 120 feet Components: V, S, M (a handful of thorns) Duration: Concentration, up to 10 minutes You create a wall or ring of piercing thorns. You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight."},{"name":"Wind Walk","circle":6,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (fire and rainwater) Duration: 8 hours You transform willing creatures into gaseous forms capable of swift flight. You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical attacks. The only actions a creature can take in this form are the Dash action or to revert to its normal form."},{"name":"Word Of Recall","circle":6,"sources":["Divine"],"school":"Conjuration","text":"Casting Time: 1 action Range: 5 feet Components: V Duration: Instantaneous You teleport nearby creatures to a chosen sanctuary. You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and creatures that teleport with you appear in an unoccupied space nearest to the spot you designated when you prepared your sanctuary. If you cast this spell without first preparing a sanctuary, the spell has no effect."},{"name":"Arcane Sword","circle":7,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a miniature platinum sword with a grip and pommel of copper and zinc worth 250 gp) Duration: Concentration, up to 1 minute You create a blade of magic energy that attacks at your command. When the sword appears, you make two melee spell attacks with the blade, each one against a target of your choice within 5 feet of the sword. On a hit, the target takes 3d10 + your spellcasting modifier force damage."},{"name":"Delayed Blast Fireball","circle":7,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: 150 feet (20-foot-radius sphere) Components: V, S, M (a tiny ball of bat guano and sulfur) Duration: Concentration, up to 1 minute You create a bead of shimmering fire, which explodes when you throw it. A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners."},{"name":"Divine Word","circle":7,"sources":["Divine"],"school":"Evocation","text":"Casting Time: 1 bonus action Range: 30 feet Components: V Duration: Instantaneous You recite a single word of divine power that harms foes and banishes supernatural creatures. You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a CHA save."},{"name":"Etherealness","circle":7,"sources":["Arcane","Wyrd"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S Duration: 8 hours You leave the material world and step into the Ethereal Plane. You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Ethereal Plane for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can see and hear the plane you originated from, but everything there looks gray, and you can’t see anything more than 60 feet away."},{"name":"Finger Of Death","circle":7,"sources":["Arcane","Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You launch negative energy at a creature, damaging it and potentially turning it into a zombie under your control. You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a CON save. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a success. A Humanoid killed by this spell rises as a zombie at the start of your next turn."},{"name":"Fire Storm","circle":7,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 150 feet Components: V, S Duration: Instantaneous You command the skies to rain down torrents of roaring flame. A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10‑foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a DEX save. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one."},{"name":"Forcecage","circle":7,"sources":["Arcane","Wyrd"],"school":"Evocation","text":"Casting Time: 1 action Range: 100 feet Components: V, S, M (ruby dust worth at least 1,500 gp) Duration: Concentration, up to 1 hour You create a nigh-inescapable cage of force to trap targets. An immobile, invisible, cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box (your choice). A prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch-diameter bars spaced 1/2 inch apart."},{"name":"Four Winds","circle":7,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 90 feet Components: V, S, M (an ivory war horn or set of pipes worth at least 500 gp) Duration: 1 minute You create four moving whirlwinds that bludgeon and fling creatures caught in their path. You stir the air to create four whirlwinds on the ground at points you can see within range. Each whirlwind is a 5-foot- radius, 30-foot-tall cylinder of swirling air centered on that point. The whirlwinds last for the duration of the spell."},{"name":"Magnificent Mansion","circle":7,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 300 feet Components: V, S, M (a miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp) Duration: 24 hours You conjure an extradimensional mansion, fully stocked with food and staffed with invisible servants. You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall."},{"name":"Mirage Arcane","circle":7,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: Sight Components: V, S Duration: 10 days You grant an illusory appearance to a huge swath of terrain. You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain’s general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road."},{"name":"Oculus Blossoms","circle":7,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: 60 feet Components: V, S, M (a seed or bulb carved with the image of an eye) Duration: 24 hours You plant several magic flowers; you can hear and see through them. You cause up to five Tiny magical flowers to sprout in spaces you can see within range. The spaces you select must contain an area suitable for supporting a living plant, such as a patch of open ground, a pot of dirt, or similar. The flowers that appear are always of a type native to the area and at a glance are indistinguishable from nonmagical flowers."},{"name":"Plane Shift","circle":7,"sources":["Divine","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a forked, metal rod worth at least 250 gp, attuned to a particular plane of existence) Duration: Instantaneous You instantly teleport yourself and other creatures to a different plane of existence. You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the city of Fandeval in the Shadow Realm, and you appear in or near that destination."},{"name":"Prismatic Spray","circle":7,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 1 action Range: Self (60-foot cone) Components: V, S Duration: Instantaneous You emit a cone of multicolored rays of light that inflict random harmful effects on each creature caught within it. Eight multicolored rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a DEX save. For each target, roll a d8 to determine which color ray affects it. d8"},{"name":"Project Image","circle":7,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 action Range: 500 feet Components: V, S, M (a small replica of you made from materials worth at least 5 gp) Duration: Concentration, up to 1 day You create an illusory copy of yourself that you can share senses with and move independently. You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends."},{"name":"Regenerate","circle":7,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a prayer wheel or an intact sleeve of snakeskin and holy water) Duration: 1 hour You slowly heal a creature you touch, restoring hit points and severed limbs. You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 HP at the start of each of its turns (10 HP each minute). 346 PLAYER'S GUIDE The target’s severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes."},{"name":"Resurrection","circle":7,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You work a miracle, bringing a soul whose end came too soon back from the dead. You touch a dead creature that has been dead for no more than a century, that didn’t die of old age, and that isn’t Undead. If its soul is free and willing, the target returns to life with all its hit points. This spell neutralizes any poisons and cures normal diseases afflicting the creature when it died."},{"name":"Reverse Gravity","circle":7,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 100 feet Components: V, S, M (a lodestone and iron filings) Duration: Concentration, up to 1 minute You reverse gravity in a huge area, causing unanchored targets to fall upwards. This spell reverses gravity in a 50-foot-radius, 100-foot‑high cylinder centered on a point within range. All creatures and objects that aren’t somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a DEX save to grab onto a fixed object it can reach, thus avoiding the fall."},{"name":"Sequester","circle":7,"sources":["Arcane","Divine"],"school":"Transmutation","text":"Casting Time: 1 action Range: Touch Components: V, S, M (a powder composed of gemstone dust worth at least 5,000 gp, which the spell consumes) Duration: Until dispelled You hide a willing creature or object away, shielding it from magical detection and keeping it in stasis until a condition is met. By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can’t be targeted by divination spells or perceived through scrying sensors created by divination spells."},{"name":"Simulacrum","circle":7,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 12 hours Range: Touch Components: V, S, M (snow or ice in quantities sufficient to make a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature’s body placed inside the snow or ice; and powdered ruby worth 1,500 gp sprinkled over the duplicate, which the spell consumes) Duration: Until dispelled You create a facsimile of a creature from snow, bits of hair, and crystalline dust. You shape an illusory duplicate of one Beast or Humanoid that is within range for the entire casting time of the spell."},{"name":"Symbol","circle":7,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes) Duration: Until dispelled or triggered You inscribe a nigh-invisible glyph to ward something or some place with a potent effect of your choice. When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest)."},{"name":"Teleport","circle":7,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 10 feet Components: V Duration: Instantaneous You teleport yourself and willing creatures or an object to a familiar destination anywhere on your current plane of existence. This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can’t be held or carried by an unwilling creature. DESTINATION ACCURACY"},{"name":"Transmogrification","circle":7,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S, M (flesh from a Fiend, a feather from a Celestial, or a scale from a Dragon worth 50 gp) Duration: 1 minute You rapidly transform parts of your body to give yourself monstrous traits. You transform your body to grant yourself benefits of monstrous forms. When you cast this spell, choose one of the listed transformations that your form first assumes. While the spell is active, you can use a bonus action to exchange your current transformation for a different option you haven’t already used during this casting of the spell."},{"name":"Animal Shapes","circle":8,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S Duration: Concentration, up to 24 hours You transform a group of willing creatures into animals. Your magic turns others into animals. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller Beast or creature with the Animal tag with a CR 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms. The transformation lasts for the duration for each target or until the target drops to 0 HP or dies."},{"name":"Antimagic Field","circle":8,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self (10-foot-radius sphere) Components: V, S, M (powdered iron or iron filings) Duration: Concentration, up to 1 hour You weave a sphere around you that suppresses all magic. A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can’t be cast, summoned creatures disappear, and even magic items become mundane. Until the spell ends, the sphere moves with you, centered on you."},{"name":"Antipathy/Sympathy","circle":8,"sources":["Arcane","Divine","Primordial","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 hour Range: 60 feet Components: V, S, M (either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect) Duration: 10 days You generate a semi-persistent aura that attracts or repels certain creatures. This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200- foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires."},{"name":"Clone","circle":8,"sources":["Arcane"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 1,000 gp; at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes; and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water) Duration: Instantaneous You create a spare body for a creature of your choice as a contingency plan. This spell grows an inert duplicate of a living creature as a safeguard against death."},{"name":"Control Weather","circle":8,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Self (5-mile radius) Components: V, S, M (burning incense and bits of earth and wood mixed in water) Duration: Concentration, up to 8 hours You command the weather to change to suit your wishes. You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don’t have a clear path to the sky ends the spell early. When you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season."},{"name":"Demiplane","circle":8,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: S Duration: 1 hour You conjure a doorway to a separate, smaller plane of existence. You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there, as the door also disappears from the other side."},{"name":"Earthquake","circle":8,"sources":["Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 500 feet (100-foot-radius circle) Components: V, S, M (a pinch of dirt, a piece of rock, and a lump of clay) Duration: Concentration, up to 1 minute You command the earth to quake, opening great fissures, toppling structures, and harming creatures. You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point and shakes creatures and structures in contact with the ground in that area."},{"name":"Feeblemind","circle":8,"sources":["Arcane"],"school":"Enchantment","text":"Casting Time: 1 action Range: 150 feet Components: V, M (a handful of clay, crystal, glass, or mineral spheres) Duration: Instantaneous You shred the mind of a creature within range, rendering it incapable of complex thought. You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an INT save. On a failed save, the creature’s INT and CHA become 1 (−5). The creature can’t cast spells, activate magic items, understand language, or communicate in any intelligible way."},{"name":"Glibness","circle":8,"sources":["Arcane","Divine"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V Duration: Concentration, up to 1 hour You become irresistibly compelling and perceived as trustworthy by all others. Until the spell ends, when you make a CHA ability check or save, you can replace the number you roll with a 15. In addition, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."},{"name":"Greater Dominate","circle":8,"sources":["Arcane","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 1 hour You charm a creature, establishing a mental link and allowing you control of their actions. You attempt to beguile any creature that you can see within range. This spell has no effect on creatures immune to the charmed condition. The target must succeed on a WIS save or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the save."},{"name":"Holy Aura","circle":8,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 1 action Range: Self Components: V, S, M (a tiny reliquary worth at least 1,000 gp containing a sacred relic, such as a scrap of cloth from a saint’s robe) Duration: Concentration, up to 1 minute You emit a holy aura that protects allies standing near you and blinds profane creatures that attack them. Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you."},{"name":"Incendiary Cloud","circle":8,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 action Range: 150 feet (20-foot-radius sphere) Components: V, S Duration: Concentration, up to 1 minute You conjure a flaming cloud that burns creatures caught within it. A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it. When the cloud appears, each creature in it must make a DEX save."},{"name":"Maze","circle":8,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Concentration, up to 10 minutes You send one creature to a nigh-inescapable maze on another plane of existence. You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze. The target can use its action to attempt to escape. When it does so, it makes a DC 20 INT check. If it succeeds, it escapes, and the spell ends."},{"name":"Mind Blank","circle":8,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S Duration: 24 hours You shield a creature from psychic damage, magical detection, and mind-altering effects. Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target’s mind or to gain information about the target. 296 PLAYER'S GUIDE"},{"name":"Power Word Stun","circle":8,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You utter an arresting word that stuns a creature. You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dazed. If the target has 150 HP or fewer, it is stunned. Otherwise, the spell has no effect. The stunned target must make a CON save at the end of each of its turns, ending the effect on itself on a success. 301 7 SPELLCASTING"},{"name":"Sunburst","circle":8,"sources":["Divine","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 150 feet (60-foot-radius sphere) Components: V, S, M (fire and a piece of sunstone) Duration: Instantaneous You create a sphere of searing and blinding sunlight. Brilliant sunlight flashes in a 60-foot-radius sphere centered on a point you choose within range. Each creature in that light must make a CON save. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn’t blinded by this spell. Undead have disadvantage on this save."},{"name":"Tidal Wave","circle":8,"sources":["Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 1 mile Components: V, S Duration: Concentration, up to 1 minute You conjure a massive wave that batters and drags creatures caught in its wake. You cause a massive wave to appear at a point you can see within range. When you cast this spell, the wave appears as a wall of water 300 feet long, 300 feet high, and 50 feet thick. Huge or smaller creatures in the wave’s area when it appears are automatically caught in the wave and must make a STR save. On a failure, a creature takes 6d10 bludgeoning damage or half as much damage on a success."},{"name":"Astral Projection","circle":9,"sources":["Arcane","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 hour Range: 10 feet Components: V, S, M (for each creature you affect with this spell, you must provide one jacinth worth at least 1,000 gp and one ornately carved bar of silver worth at least 100 gp, all of which the spell consumes) Duration: Special You place yourself and several others into a deep sleep and transport your consciousnesses into the Astral Plane. You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane)."},{"name":"Foresight","circle":9,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a gilded hourglass worth at least 500 gp, which the spell consumes) Duration: 8 hours Your touch gives a creature the power to see into the future, increasing its reaction time and making it harder to hit. You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can’t be surprised and has advantage on attack rolls, ability checks, and saves. In addition, other creatures have disadvantage on attack rolls against the target for the duration."},{"name":"Gate","circle":9,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S, M (a diamond worth at least 5,000 gp) Duration: Concentration, up to 1 hour You open a portal to another plane of existence. You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration. The portal has a front and a back on each plane where it appears."},{"name":"Imprisonment","circle":9,"sources":["Arcane","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a vellum depiction or a carved statuette in the likeness of the target and a special component that varies according to the version of the spell you choose worth at least 500 gp per hit die of the target) Duration: Until dispelled You place a creature in a nigh-inescapable magical prison. You create a magical restraint to hold a creature that you can see within range. The target must succeed on a WIS save or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again."},{"name":"Mass Heal","circle":9,"sources":["Divine","Primordial"],"school":"Necromancy","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: Instantaneous You heal nearby creatures for a massive amount and also end all physical afflictions affecting them. A flood of healing energy flows from you into injured creatures around you. You restore up to 700 HP, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on Constructs or Undead. 294 PLAYER'S GUIDE"},{"name":"Metamorphosis","circle":9,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (raw silk worth 1,000 gp, which the spell consumes) Duration: Instantaneous You permanently transform a willing creature’s physical characteristics. You touch a willing creature and transform it in one of the following four ways (the target must agree with the option you choose): • If the creature is Humanoid, you can change its lineage to any other lineage you choose. It loses any traits and abilities associated with its former lineage and gains any traits and abilities of the new lineage."},{"name":"Meteor Swarm","circle":9,"sources":["Arcane","Primordial"],"school":"Evocation","text":"Casting Time: 1 action Range: 1 mile (40-foot-radius sphere) Components: V, S Duration: Instantaneous You command the skies to rain down flaming meteors that devastate creatures and objects in the area. Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot- radius sphere centered on each point you choose must make a DEX save. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one."},{"name":"Power Word Kill","circle":9,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You utter a profane word that instantly kills a weak or injured creature. You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 HP or fewer, it dies. Otherwise, the spell has no effect."},{"name":"Power Word Recover","circle":9,"sources":["Divine"],"school":"Enchantment","text":"Casting Time: 1 action Range: 60 feet Components: V Duration: Instantaneous You utter a divine word that restores a creature to perfect health. You utter a word of power that completely heals one creature you can see within range. The creature is restored to maximum hit points. In addition, any charmed, frightened, paralyzed, or stunned conditions affecting the target immediately end. This spell has no effect on Constructs or Undead."},{"name":"Prismatic Wall","circle":9,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: 60 feet Components: V, S Duration: 10 minutes You create a wall or sphere of scintillating colors that blinds creatures and punishes those who pass through it with seven effects. A shimmering, multicolored plane of light forms a vertical, opaque wall—up to 90 feet long, 30 feet high, and 1 inch thick—centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration."},{"name":"Shapechange","circle":9,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V, S, M (a jade circlet worth at least 1,500 gp, which you must place on your head before you cast the spell) Duration: Concentration, up to 1 hour You can assume the forms of different creatures for an hour. You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can’t be a Construct or an Undead, and you must have seen the sort of creature at least once."},{"name":"Storm Of Vengeance","circle":9,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 1 action Range: Sight Components: V, S Duration: Concentration, up to 1 minute You conjure a potent magical storm that affects a huge area, unleashing more devastating effects the longer it lasts. A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a CON save. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes."},{"name":"Time Stop","circle":9,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 action Range: Self Components: V Duration: Instantaneous You stop time for a brief window, allowing you to take multiple turns before others can act. You briefly stop the flow of time for everyone but yourself. No time passes for other creatures while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal. This spell ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you."},{"name":"True Polymorph","circle":9,"sources":["Arcane","Primordial"],"school":"Transmutation","text":"Casting Time: 1 action Range: 30 feet Components: V, S, M (a drop of mercury, a dollop of gum arabic, and a wisp of smoke) Duration: Concentration, up to 1 hour You transform a creature into a different creature or an object, or you transform an object into a creature. Choose one creature or nonmagical object that you can see within range. You transform the creature into a different creature, the creature into an object, or the object into a creature (the object must be neither worn nor carried by another creature)."},{"name":"True Resurrection","circle":9,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a sprinkle of holy water and diamonds worth at least 25,000 gp, which the spell consumes) Duration: Instantaneous You bring a dead soul back to life and banish all diseases, curses, and ailments that affected them in life. You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature’s soul is free and willing, the creature is restored to life with all its hit points."},{"name":"Weird","circle":9,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 action Range: 120 feet (30-foot-radius sphere) Components: V, S Duration: Concentration, up to 1 minute You manifest the worst nightmares of multiple creatures to frighten them and damage their minds. Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a WIS save. On a failed save, a creature becomes frightened of you for the duration."},{"name":"Wish","circle":9,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 action Range: Self Components: V Duration: Instantaneous You alter the foundations of reality but risk never being able to do so again. Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires. The basic use of this spell is to duplicate any other spell of 8th circle or lower. You don’t need to meet any requirements in that spell, including costly components. The spell simply takes effect."}]

/** How a class gets its 1st-circle spells at 1st level. */
export type FirstCircleMode =
  /** Knows a fixed number of spells from the source list. */
  | { mode: 'known'; count: number }
  /** Prepares (ability modifier + class level) spells from the whole source list. */
  | { mode: 'prepared'; ability: Ability }
  /** Records spells in a spellbook, then prepares a subset. */
  | { mode: 'spellbook'; count: number; prepareAbility: Ability }
  /** No 1st-circle spells at 1st level (e.g. cantrips-only / half-casters). */
  | { mode: 'none' }

export interface SpellcastingInfo {
  source: SpellSource
  /** Cantrips known at 1st level, or null if the class learns none at L1. */
  cantripsKnown: number | null
  /** How 1st-circle spells are chosen. */
  firstCircle: FirstCircleMode
  /** Extra guidance for the player. */
  note?: string
}

/** Per-class spellcasting at 1st level (null = casts no spells at 1st level). */
export const SPELLCASTING: Record<string, SpellcastingInfo | null> = {
  barbarian: null,
  bard: {
    source: 'Arcane', cantripsKnown: 3, firstCircle: { mode: 'known', count: 4 },
    note: 'Bards know their spells.',
  },
  cleric: {
    source: 'Divine', cantripsKnown: 3, firstCircle: { mode: 'prepared', ability: 'wis' },
    note: 'Clerics prepare spells from the whole Divine list and can change the list after a long rest.',
  },
  druid: {
    source: 'Primordial', cantripsKnown: 3, firstCircle: { mode: 'prepared', ability: 'wis' },
    note: 'Druids prepare spells from the whole Primordial list and can change the list after a long rest.',
  },
  fighter: null,
  mechanist: null, // Mechanist has no Spellcasting feature at 1st level.
  monk: null,
  paladin: {
    source: 'Divine', cantripsKnown: null, firstCircle: { mode: 'none' },
    note: 'Paladins are half-casters and gain spells at 2nd level — nothing to choose at 1st.',
  },
  ranger: {
    source: 'Primordial', cantripsKnown: null, firstCircle: { mode: 'known', count: 2 },
    note: 'Rangers know their spells (no cantrips).',
  },
  rogue: null,
  sorcerer: {
    source: 'Arcane', cantripsKnown: 3, firstCircle: { mode: 'known', count: 2 },
    note: 'Sorcerers know their spells.',
  },
  warlock: {
    source: 'Wyrd', cantripsKnown: 3, firstCircle: { mode: 'none' },
    note: 'Warlocks choose 3 cantrips at 1st level (from any list); known Wyrd spells begin at 2nd level.',
  },
  wizard: {
    source: 'Arcane', cantripsKnown: 3,
    firstCircle: { mode: 'spellbook', count: 6, prepareAbility: 'int' },
    note: 'Wizards record spells in a spellbook, then prepare INT modifier + level of them each day.',
  },
}

export function spellcastingFor(classId: string | null): SpellcastingInfo | null {
  return classId ? (SPELLCASTING[classId] ?? null) : null
}

export function classSpellSource(classId: string | null): SpellSource | null {
  return spellcastingFor(classId)?.source ?? null
}

export function spellsFor(source: SpellSource, circle: number): Spell[] {
  return SPELLS.filter((s) => s.circle === circle && s.sources.includes(source)).sort(
    (a, b) => a.name.localeCompare(b.name),
  )
}
